#!/usr/bin/env python3
# Generates lexicon-part-e.json: reusable semantic routing families (intent -> concept/technology -> guide),
# a spelling-normalisation map, and negative-context protection for ambiguous technology words.
# Written after the independent red-team baseline; families describe HOW people ask about a topic and are
# deliberately broader than any single failed query. The build reads only the JSON.
import json, sys
I = []
def fam(i, phrases, *pages):
    I.append({"id": "rt-" + i, "phrases": phrases, "pages": [{"id": p, "boost": b} for p, b in pages]})

